static NSUInteger checks;
static void Check(BOOL ok,NSString *label){checks++;if(!ok){NSLog(@"FAIL %@",label);exit(1);}}
static NSData *Encoded(id value){return [NSJSONSerialization dataWithJSONObject:value options:NSJSONWritingSortedKeys error:nil];}
static NSString *JSONString(id value){return [[NSString alloc]initWithData:Encoded(value) encoding:NSUTF8StringEncoding];}
static NSString *Large(NSUInteger n){return [@"// source line 1234567890\n" stringByPaddingToLength:n withString:@"// source line 1234567890\n" startingAtIndex:0];}
static NSMutableArray *Fixture(NSUInteger count,BOOL legacy){NSMutableArray *m=[NSMutableArray arrayWithObjects:@{@"role":@"system",@"content":@"Keep approvals; project A."},@{@"role":@"user",@"content":@"Fix this project without deleting unrelated files."},nil];for(NSUInteger i=0;i<count;i++){NSString *identifier=[NSString stringWithFormat:@"patch-%lu",(unsigned long)i];[m addObject:@{@"role":@"assistant",@"content":@"Prepare patch only.",@"tool_calls":@[@{@"id":identifier,@"name":@"propose_patch",@"arguments":@{@"edits":@[@{@"path":@"Tweak.xm",@"before":Large(48*1024),@"after":Large(48*1024+1)}]}}]}];NSDictionary *result=legacy?@{@"error":@"Not applied; original text mismatch",@"full_diff":Large(120*1024)}:@{@"proposal_id":identifier,@"edit_count":@1,@"previewStoredLocally":@YES};[m addObject:@{@"role":@"tool",@"tool_call_id":identifier,@"content":JSONString(result)}];}return m;}
static void Pairs(NSArray *messages){NSMutableSet *calls=[NSMutableSet new],*results=[NSMutableSet new];for(NSDictionary *m in messages){for(NSDictionary *c in m[@"tool_calls"])[calls addObject:c[@"id"]];if([m[@"role"] isEqual:@"tool"])[results addObject:m[@"tool_call_id"]];}Check([calls isEqual:results],@"complete tool pairs retained");}
