 NSString *oldReport=Large(290*1024);[longChat addObject:@{@"role":@"assistant",@"content":oldReport}];[longChat addObject:@{@"role":@"user",@"content":@"测试一下 token 用量"}];
 NSData *longOriginal=Encoded(longChat);error=nil;out=[TFAIContextProjection project:longChat schemas:schemas statistics:&stats error:&error];
